function parseCSV(text) {
  return Papa.parse(text, { header: true, skipEmptyLines: true }).data;
}
function loadCustomers() {
  return parseCSV(CSV_CUSTOMERS);
}
function loadListings() {
  return parseCSV(CSV_LISTINGS).map((l) => ({
    ...l,
    hourly_rate: parseFloat(l.hourly_rate),
    availability_slots: (() => {
      try {
        return JSON.parse(l.availability_slots || "[]");
      } catch (e) {
        return [];
      }
    })(),
  }));
}
function loadBookingsCSV() {
  return parseCSV(CSV_BOOKINGS).map((b) => ({ ...b, total_cost: parseFloat(b.total_cost) }));
}
function loadTrustSafetyCSV() {
  return parseCSV(CSV_TRUST_SAFETY);
}

function money(n) {
  if (n === undefined || n === null || Number.isNaN(n)) return "\u2014";
  return `$${Number(n).toFixed(2)}`;
}
function dateTime(iso) {
  if (!iso) return "\u2014";
  try {
    const d = new Date(iso);
    return d.toLocaleString(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
  } catch (e) {
    return iso;
  }
}
function titleCase(s) {
  if (!s) return "";
  return s.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}
function randomId(prefix, digits) {
  let n = "";
  for (let i = 0; i < digits; i++) n += Math.floor(Math.random() * 10);
  return `${prefix}_${n}`;
}

