/* ============================================================
   Providers column (middle) — grouped by generated business name
   (since the sample dataset gives each provider_id its own row
   but only a small pool of placeholder names per category, the
   same name legitimately repeats — this groups those repeats
   into one expandable entry instead of showing the same name
   over and over). Each provider_id inside a group is labeled
   "Team {id}" so the repetition reads as multiple crews under one
   business rather than unexplained duplicate numbers.
   ============================================================ */
function ProvidersColumn({ providersByGroup, onSelectProvider, selectedListingId, providerCount }) {
  const CATEGORY_OPTIONS = ["all", "cleaning", "handyman", "moving"];
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [sortMode, setSortMode] = useState("name");
  const [expanded, setExpanded] = useState(false);
  const [expandedGroups, setExpandedGroups] = useState(() => new Set());
  const COLLAPSED_COUNT = 5;

  const groups = useMemo(() => {
    const flat =
      categoryFilter === "all"
        ? Object.values(providersByGroup).flat()
        : providersByGroup[categoryFilter] || [];
    const byKey = {};
    flat.forEach((p) => {
      const displayName = placeholderProviderName(p.provider_id, p.service_type);
      const key = `${p.service_type}::${displayName}`;
      if (!byKey[key]) byKey[key] = { key, displayName, service_type: p.service_type, members: [] };
      byKey[key].members.push(p);
    });
    let list = Object.values(byKey).map((g) => ({ ...g, minRate: Math.min(...g.members.map((m) => m.minRate)) }));
    if (sortMode === "price-asc") list.sort((a, b) => a.minRate - b.minRate);
    else if (sortMode === "price-desc") list.sort((a, b) => b.minRate - a.minRate);
    else list.sort((a, b) => a.displayName.localeCompare(b.displayName));
    return list;
  }, [providersByGroup, categoryFilter, sortMode]);

  useEffect(() => {
    setExpanded(false);
    setExpandedGroups(new Set());
  }, [categoryFilter]);

  function toggleGroup(key) {
    setExpandedGroups((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  }

  const visibleGroups = expanded ? groups : groups.slice(0, COLLAPSED_COUNT);

  return (
    <div className="p-4">
      {/* Sticky header cluster — heading, CTAs, filter, and sort controls
          all stay pinned at the top of this column's own scroll area,
          the same treatment used for the Ad column's tagline card. */}
      <div className="space-y-3 shrink-0" style={{ position: "sticky", top: 0, zIndex: 5, background: "#0F1B2E", paddingBottom: "10px" }}>
        <div>
          <p className="text-[15px] font-bold" style={{ color: "#39FF14", fontFamily: "'Space Grotesk', sans-serif" }}>
            Providers
          </p>
          <p className="text-xs" style={{ color: "#7C93B3" }}>
            Click a team to ask the assistant about them.
          </p>
        </div>

        <div
          className="rounded-lg px-3 py-1.5 flex items-center justify-between gap-2"
          style={{ background: "linear-gradient(120deg, #1B2B44, #16233A)", border: "1px solid #FF6B35" }}
        >
          <p className="text-[13px] truncate" style={{ color: "#F5F3EE" }}>
            <span className="font-bold" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>
              Become a provider
            </span>
            <span style={{ color: "#C7D0DE" }}> — join {providerCount} earning on TaskLocal</span>
          </p>
          <button type="button" className="text-[13px] font-semibold px-2.5 py-1 rounded-md shrink-0" style={{ background: "#FF6B35", color: "#0F1B2E", fontFamily: "'Space Grotesk', sans-serif" }}>
            Sign up
          </button>
        </div>

        <div>
          <label className="text-[11px] uppercase tracking-wider block mb-1" style={{ color: "#7C93B3", fontFamily: "'Space Grotesk', sans-serif" }}>
            Select a Service Type
          </label>
          <select
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
            className="w-full text-[13px] px-2 py-1.5 rounded"
            style={{ background: "#16233A", color: "#F5F3EE", border: "1px solid #23324A" }}
          >
            {CATEGORY_OPTIONS.map((c) => (
              <option key={c} value={c}>
                {c === "all" ? "All services" : titleCaseWord(c)}
              </option>
            ))}
          </select>
        </div>

        <div className="flex items-center justify-between px-1">
          <button
            onClick={() => setSortMode("name")}
            className="text-[13px] uppercase tracking-wider flex items-center gap-1"
            style={{ color: sortMode === "name" ? "#39FF14" : "#7C93B3", fontFamily: "'Space Grotesk', sans-serif" }}
          >
            List of Current Providers - A - Z (click to resort)
            {categoryFilter !== "all" && ` (${titleCaseWord(categoryFilter)})`}
          </button>
          <button
            onClick={() => setSortMode(sortMode === "price-asc" ? "price-desc" : "price-asc")}
            className="text-[13px] uppercase tracking-wider flex items-center gap-1"
            style={{ color: sortMode.startsWith("price") ? "#39FF14" : "#7C93B3", fontFamily: "'Space Grotesk', sans-serif" }}
          >
            Price {sortMode === "price-asc" ? "↑" : sortMode === "price-desc" ? "↓" : ""}
          </button>
        </div>
      </div>

      <div className="space-y-1.5 mt-3">
        {visibleGroups.map((g) => {
          const isOpen = expandedGroups.has(g.key);
          return (
            <div key={g.key} className="rounded-lg overflow-hidden" style={{ border: "1px solid #23324A" }}>
              <button
                onClick={() => toggleGroup(g.key)}
                className="w-full text-left px-3 py-2 flex items-center justify-between gap-2"
                style={{ background: "#16233A" }}
              >
                <div className="min-w-0">
                  <p className="text-sm font-semibold truncate" style={{ color: "#F5F3EE", maxWidth: "170px" }}>
                    {g.displayName}
                  </p>
                  <p className="text-[11px] mt-0.5" style={{ color: "#7C93B3" }}>
                    {g.members.length} team{g.members.length > 1 ? "s" : ""}
                  </p>
                </div>
                <div className="text-right shrink-0">
                  <p className="text-[13px] font-semibold" style={{ color: "#F5F3EE" }}>
                    from ${g.minRate.toFixed(0)}/hr
                  </p>
                  <p className="text-[11px]" style={{ color: "#7C93B3" }}>
                    {isOpen ? "− hide" : "+ expand"}
                  </p>
                </div>
              </button>
              {isOpen && (
                <div style={{ background: "#0F1B2E" }}>
                  {g.members.map((m) => (
                    <button
                      key={m.provider_id}
                      onClick={() => onSelectProvider(m)}
                      className="w-full text-left px-3 py-1.5 flex items-center justify-between gap-2"
                      style={{
                        borderTop: "1px solid #1B2B44",
                        background: selectedListingId === m.listing_id ? "#1B2B44" : "transparent",
                      }}
                    >
                      <p className="text-[13px]" style={{ color: "#C7D0DE" }}>
                        Team {m.provider_id.replace("prov_", "")}
                      </p>
                      <p className="text-[13px] font-semibold" style={{ color: "#F5F3EE" }}>
                        ${m.minRate.toFixed(0)}/hr
                      </p>
                    </button>
                  ))}
                </div>
              )}
            </div>
          );
        })}
        {visibleGroups.length === 0 && (
          <p className="text-xs text-center py-4" style={{ color: "#7C93B3" }}>
            No providers in this category.
          </p>
        )}

        {groups.length > COLLAPSED_COUNT && (
          <button
            onClick={() => setExpanded(!expanded)}
            className="w-full text-center text-[13px] font-semibold py-2 rounded-lg"
            style={{
              fontFamily: "'Space Grotesk', sans-serif",
              color: "#39FF14",
              border: "1px solid #23324A",
              background: "#16233A",
            }}
          >
            {expanded ? "Show less" : `Show all ${groups.length} businesses`}
          </button>
        )}

        <p className="text-xs pt-1" style={{ color: "#3A4C6B" }}>
          No service-area data in this dataset yet. Names are generated placeholders, grouped per business — provider_id is the real identifier.
        </p>
      </div>
    </div>
  );
}

/* ============================================================
   Top-level 3-column page — providers on the left, analytics in
   the center, the full approved chat assistant on the right.
   Owns the shared in-memory dataset and the tool-calling logic
   the assistant's tools read and write.
   ============================================================ */
export default function TaskLocalDashboard3Col({ user, onLogout }) {
  const [customers] = useState(() => parseCSV(CSV_CUSTOMERS));
  const [listings, setListings] = useState(() => parseCSV(CSV_LISTINGS).map((l) => ({
    ...l,
    hourly_rate: parseFloat(l.hourly_rate),
    availability_slots: (() => {
      try {
        return JSON.parse(l.availability_slots || "[]");
      } catch (e) {
        return [];
      }
    })(),
  })));

  const [bookings, setBookings] = useState(() => parseCSV(CSV_BOOKINGS).map((b) => ({ ...b, total_cost: parseFloat(b.total_cost) })));
  const [trustSafety, setTrustSafety] = useState(() => parseCSV(CSV_TRUST_SAFETY));
  const [chatbotRequests] = useState(() => parseCSV(CSV_CHATBOT_REQUESTS));

  const bookingsRef = useRef(bookings);
  const trustSafetyRef = useRef(trustSafety);
  useEffect(() => {
    bookingsRef.current = bookings;
  }, [bookings]);
  useEffect(() => {
    trustSafetyRef.current = trustSafety;
  }, [trustSafety]);

  const listingsById = useRef({});
  useEffect(() => {
    const map = {};
    listings.forEach((l) => (map[l.listing_id] = l));
    listingsById.current = map;
  }, [listings]);

  const [currentCustomerId, setCurrentCustomerId] = useState(customers[0] ? customers[0].customer_id : "");
  const chatRef = useRef(null);
  const [selectedListingId, setSelectedListingId] = useState(null);

  function runTool(name, input) {
    switch (name) {
      case "search_listings": {
        let results = listings.slice();
        if (input.service_type) results = results.filter((l) => l.service_type === input.service_type);
        if (input.max_rate != null) results = results.filter((l) => l.hourly_rate <= input.max_rate);
        if (input.keywords) {
          const kw = input.keywords.toLowerCase();
          results = results.filter((l) => l.title.toLowerCase().includes(kw) || l.description.toLowerCase().includes(kw));
        }
        results.sort((a, b) => a.hourly_rate - b.hourly_rate);
        const limit = Math.min(input.limit || 5, 10);
        return {
          count_matched: results.length,
          results: results.slice(0, limit).map((l) => ({
            listing_id: l.listing_id,
            title: l.title,
            service_type: l.service_type,
            hourly_rate: l.hourly_rate,
            provider_id: l.provider_id,
            next_availability: l.availability_slots[0] || null,
            description: l.description,
          })),
        };
      }
      case "get_listing": {
        const l = listingsById.current[input.listing_id];
        if (!l) return { error: `No listing with id ${input.listing_id}` };
        const flags = trustSafetyRef.current.filter((t) => t.reference_type === "listing_id" && t.reference_id === input.listing_id);
        return { listing: l, open_reports: flags };
      }
      case "create_booking": {
        const l = listingsById.current[input.listing_id];
        if (!l) return { error: `No listing with id ${input.listing_id}` };
        const custExists = customers.some((c) => c.customer_id === input.customer_id);
        if (!custExists) return { error: `No customer with id ${input.customer_id}` };
        const commission = 0.15;
        const booking = {
          booking_id: randomId("bkg", 6),
          customer_id: input.customer_id,
          listing_id: input.listing_id,
          booking_status: "pending",
          total_cost: Math.round(l.hourly_rate * (1 + commission) * 100) / 100,
        };
        const next = [booking, ...bookingsRef.current];
        bookingsRef.current = next;
        setBookings(next);
        return { created: booking, listing_title: l.title };
      }
      case "get_customer_bookings": {
        const rows = bookingsRef.current
          .filter((b) => b.customer_id === input.customer_id)
          .map((b) => {
            const l = listingsById.current[b.listing_id];
            return {
              booking_id: b.booking_id,
              listing_title: l ? l.title : b.listing_id,
              service_type: l ? l.service_type : null,
              booking_status: b.booking_status,
              total_cost: b.total_cost,
            };
          });
        return { count: rows.length, bookings: rows };
      }
      case "update_booking_status": {
        const idx = bookingsRef.current.findIndex((b) => b.booking_id === input.booking_id);
        if (idx === -1) return { error: `No booking with id ${input.booking_id}` };
        const next = bookingsRef.current.slice();
        next[idx] = { ...next[idx], booking_status: input.status };
        bookingsRef.current = next;
        setBookings(next);
        return { updated: next[idx] };
      }
      case "check_trust_safety": {
        const rows = trustSafetyRef.current.filter((t) => t.reference_type === input.reference_type && t.reference_id === input.reference_id);
        return { count: rows.length, reports: rows };
      }
      case "file_safety_report": {
        const report = {
          report_id: randomId("rpt", 5),
          reference_type: input.reference_type,
          reference_id: input.reference_id,
          flag_status: "pending_review",
          flag_type: input.flag_type,
          rating: input.flag_type === "low_rating" ? input.rating || "" : "",
        };
        const next = [report, ...trustSafetyRef.current];
        trustSafetyRef.current = next;
        setTrustSafety(next);
        return { filed: report };
      }
      case "dataset_summary": {
        const byService = {};
        listings.forEach((l) => (byService[l.service_type] = (byService[l.service_type] || 0) + 1));
        const byBookingStatus = {};
        bookingsRef.current.forEach((b) => (byBookingStatus[b.booking_status] = (byBookingStatus[b.booking_status] || 0) + 1));
        const byFlagStatus = {};
        trustSafetyRef.current.forEach((t) => (byFlagStatus[t.flag_status] = (byFlagStatus[t.flag_status] || 0) + 1));
        return {
          customers: customers.length,
          listings: listings.length,
          listings_by_service: byService,
          bookings: bookingsRef.current.length,
          bookings_by_status: byBookingStatus,
          reports: trustSafetyRef.current.length,
          reports_by_status: byFlagStatus,
        };
      }
      default:
        return { error: `Unknown tool ${name}` };
    }
  }

  /* ---------------- derived data for the left + center columns ---------------- */
  const providers = useMemo(() => {
    const byId = {};
    listings.forEach((l) => {
      if (!byId[l.provider_id]) {
        byId[l.provider_id] = {
          provider_id: l.provider_id,
          listing_id: l.listing_id,
          service_type: l.service_type,
          minRate: l.hourly_rate,
          sampleTitle: l.title,
        };
      }
    });
    return Object.values(byId);
  }, [listings]);

  const providersByGroup = useMemo(() => {
    const groups = { cleaning: [], handyman: [], moving: [], custom: [] };
    providers.forEach((p) => {
      if (groups[p.service_type]) groups[p.service_type].push(p);
    });
    Object.values(groups).forEach((list) => list.sort((a, b) => a.minRate - b.minRate));
    return groups;
  }, [providers]);

  const providersByCategory = useMemo(() => {
    const counts = {};
    providers.forEach((p) => (counts[p.service_type] = (counts[p.service_type] || 0) + 1));
    return ["cleaning", "handyman", "moving"].filter((s) => counts[s]).map((s) => ({ service_type: s, count: counts[s] }));
  }, [providers]);

  const providerRatings = useMemo(() => {
    const ratings = {};
    trustSafety
      .filter((t) => t.flag_type === "low_rating" && t.rating)
      .forEach((t) => {
        let listing = null;
        if (t.reference_type === "listing_id") listing = listingsById.current[t.reference_id];
        else {
          const b = bookings.find((bk) => bk.booking_id === t.reference_id);
          if (b) listing = listingsById.current[b.listing_id];
        }
        if (!listing) return;
        const pid = listing.provider_id;
        if (!ratings[pid]) ratings[pid] = { provider_id: pid, values: [], title: listing.title };
        ratings[pid].values.push(Number(t.rating));
      });
    return Object.values(ratings)
      .map((r) => ({ ...r, avg: r.values.reduce((a, b) => a + b, 0) / r.values.length, count: r.values.length }))
      .sort((a, b) => b.avg - a.avg || b.count - a.count);
  }, [trustSafety, bookings, listings]);

  // Real sample ratings skew low (small dataset), which reads badly as a
  // headline stat — bumped per your call, since this is synthetic demo
  // data. The "Highest rated providers" list still uses the real,
  // differentiated per-provider averages, unchanged.
  const overallAvgRating = 4.5;

  const bookingsByStatus = (() => {
    const counts = {};
    bookings.forEach((b) => (counts[b.booking_status] = (counts[b.booking_status] || 0) + 1));
    return ["draft", "pending", "confirmed", "completed"].filter((s) => counts[s]).map((s) => ({ name: titleCaseWord(s), value: counts[s], key: s }));
  })();

  const classifiedRequests = chatbotRequests.map((r) => ({ text: r.job_request_text, service: classifyRequest(r.job_request_text || "") }));
  const autoRoutedPct = classifiedRequests.length
    ? Math.round((classifiedRequests.filter((r) => r.service !== "custom").length / classifiedRequests.length) * 100)
    : 0;

  const notifications = (() => {
    const listingsByIdMap = {};
    listings.forEach((l) => (listingsByIdMap[l.listing_id] = l));
    return generateNotifications(bookings, listingsByIdMap);
  })();

  function handleSelectProvider(p) {
    setSelectedListingId(p.listing_id);
    const text = `Tell me about "${p.sampleTitle}" — listing ${p.listing_id} from provider ${p.provider_id}. Is it a good pick, and is there anything I should know before booking?`;
    if (chatRef.current) chatRef.current.sendMessage(text);
  }

  return (
    <div className="h-screen w-full flex overflow-hidden" style={{ background: "#0F1B2E", fontFamily: "'IBM Plex Sans', sans-serif", color: "#F5F3EE" }}>
      {/* Left+center area: top row is Ad | Providers, bottom row is Analytics
          spanning the full width of this area. */}
      <div className="flex-1 min-w-0 h-full overflow-y-auto" style={{ borderRight: "1px solid #23324A" }}>
        <div className="px-4 pt-4 pb-1 flex items-center justify-between flex-wrap gap-2">
          <div className="flex items-center gap-2.5">
            <img src={TL_LOGO_SRC} alt="TaskLocal" className="h-20 w-auto object-contain" />
            <p className="text-base font-bold" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>
              TaskLocal Chat Console
            </p>
          </div>
          <div className="flex items-center gap-3">
            <label className="text-[11px] uppercase tracking-wider flex items-center gap-1.5" style={{ color: "#7C93B3" }}>
              Viewing as
              <select
                value={currentCustomerId}
                onChange={(e) => setCurrentCustomerId(e.target.value)}
                className="text-[13px] px-1.5 py-0.5 rounded"
                style={{ background: "#16233A", color: "#F5F3EE", border: "1px solid #23324A" }}
              >
                {customers.map((c) => (
                  <option key={c.customer_id} value={c.customer_id}>
                    {c.customer_id}
                  </option>
                ))}
              </select>
            </label>
            <button type="button" className="dashboard-logout" onClick={onLogout} title={`Signed in as ${user?.email}`}>
              Sign out
            </button>
          </div>
        </div>

        {/* Top half: Ad + Chat Analytics stacked (left) | Providers (middle)
            — height-capped with its own internal scroll, so Providers is
            guaranteed to show several rows below. */}
        <div
          className="grid"
          style={{ gridTemplateColumns: "minmax(260px, 1fr) minmax(320px, 1.2fr)", alignItems: "start" }}
        >
          <div style={{ borderRight: "1px solid #23324A" }}>
            <AdColumn providerCount={providers.length} listingCount={listings.length} />
            <p className="text-[15px] font-bold pl-7 pt-1" style={{ color: "#39FF14", fontFamily: "'Space Grotesk', sans-serif" }}>
              Chat Analytics
            </p>
            <AnalyticsColumn
              providersByCategory={providersByCategory}
              bookingsByStatus={bookingsByStatus}
              overallAvgRating={overallAvgRating}
              classifiedRequests={classifiedRequests}
              autoRoutedPct={autoRoutedPct}
            />
          </div>
          <div>
            <div className="overflow-y-auto" style={{ height: "calc(60vh + 80px)", minHeight: "560px" }}>
              <ProvidersColumn
                providersByGroup={providersByGroup}
                onSelectProvider={handleSelectProvider}
                selectedListingId={selectedListingId}
                providerCount={providers.length}
              />
            </div>

            {/* Notifications now lives here, filling whatever space is left
                below the Providers box in this column, instead of its own
                full-width strip at the bottom of the page. */}
            <div className="px-4" style={{ borderTop: "1px solid #23324A" }}>
              <p className="text-[15px] font-bold pt-4" style={{ color: "#39FF14", fontFamily: "'Space Grotesk', sans-serif" }}>
                Notifications
              </p>
              <p className="text-xs mb-2" style={{ color: "#7C93B3" }}>
                Live activity derived from real booking data — assignments and ETAs
              </p>
              <NotificationsPanel notifications={notifications} />
            </div>
          </div>
        </div>
      </div>

      {/* Right: the approved chat assistant, unchanged, full height */}
      <div className="shrink-0 h-full" style={{ width: "420px", background: "#F5F3EE" }}>
        <TaskLocalChat ref={chatRef} runTool={runTool} currentCustomerId={currentCustomerId} />
      </div>
    </div>
  );
}
